import sys
import math
import heapq

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        R = int(next(iterator))
        C = int(next(iterator))
    except StopIteration:
        return

    grid = []
    for _ in range(R):
        grid.append(next(iterator))

    passengers = []
    seats = []

    for r in range(R):
        for c in range(C):
            ch = grid[r][c]
            if ch == 'X':
                passengers.append((r, c))
            elif ch == 'L':
                seats.append((r, c))

    explosions = 0

    while passengers and seats:
        # Calculate distances from each passenger to all available seats
        passenger_distances = [] # (min_dist_to_seat, seat_index, seat_pos)

        for p_idx, (pr, pc) in enumerate(passengers):
            best_seat_idx = -1
            best_dist = float('inf')

            for s_idx, (sr, sc) in enumerate(seats):
                dist = math.sqrt((pr - sr)**2 + (pc - sc)**2)
                if dist < best_dist:
                    best_dist = dist
                    best_seat_idx = s_idx

            # Store the best seat index and distance for this passenger
            passenger_distances.append((best_dist, best_seat_idx))

        # Group passengers by their best seat choice
        seat_choice_groups = {}
        for i, (dist, s_idx) in enumerate(passenger_distances):
            if s_idx not in seat_choice_groups:
                seat_choice_groups[s_idx] = []
            seat_choice_groups[s_idx].append(i)

        found_a_seat = False

        # Check each seat that was targeted
        for s_idx, p_indices in seat_choice_groups.items():
            if s_idx >= len(seats):
                continue

            # Check how many passengers are targeting this seat
            if len(p_indices) == 1:
                # Only one passenger wants this seat -> he takes it
                p_idx = p_indices[0]
                _, seat_r, seat_c = seats[s_idx]
                # Verify it's still empty (it should be since we track available seats)
                if grid[seat_r][seat_c] == 'L':
                    # Passenger sits
                    grid[seat_r] = list(grid[seat_r])
                    grid[seat_r][seat_c] = '.'
                    seats.pop(s_idx)
                    passengers.pop(p_idx)
                    found_a_seat = True
            else:
                # Multiple passengers target this seat -> EXPLOSION
                explosions += 1
                # All these passengers are destroyed
                for p_idx in p_indices:
                    passengers.pop(p_idx)
                # Remove the seat
                seats.pop(s_idx)
                found_a_seat = True

        # If no seat was assigned and no explosion occurred (shouldn't happen given problem constraints logic but safety check)
        if not found_a_seat:
            break

    print(explosions)

if __name__ == '__main__':
    solve()
